const $=s=>document.querySelector(s),main=$('#main'),asset=n=>/^product-[0-3]$/.test(n)?'assets/products/'+n+'-hq.webp':n==='hero'?'assets/reference/hero-cutout.png':n==='how-0'?'assets/reference/how-0-restored.png':'assets/reference/'+n+'.webp';
const tabs={inicio:'Início',recursos:'Recursos',plataformas:'Plataformas',oportunidades:'Oportunidades',funcionamento:'Como funciona',planos:'Planos',perguntas:'Perguntas'};
let page='',slide=1,productSlide=0,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,entry,observer;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const screenSizes={"product-images": [1448, 1086], "radar-live": [1616, 973], "product-details": [1448, 1086], "product-price": [1448, 1086], "product-start": [1448, 1086], "radar-trends": [1536, 1024], "product-review": [1448, 1086], "product-category": [1448, 1086]};
const screen=(name,alt,cls='')=>`<img data-src="assets/program/${name}.webp" alt="${alt}" class="${cls} queued-image" width="${screenSizes[name]?.[0]||1448}" height="${screenSizes[name]?.[1]||1086}" decoding="async">`;
const img=(name,alt,cls='',extra='')=>`<img data-src="${asset(name)}" alt="${alt}" class="${cls} queued-image" ${/^product-[0-3]$/.test(name)?'width="1024" height="1024"':''} decoding="async">`;
const imageQueue=[],knownImages=new WeakSet();let activeImages=0;
function enqueueImages(root){
 root.querySelectorAll('img[data-src]').forEach(el=>{if(knownImages.has(el))return;knownImages.add(el);const path=el.dataset.src;imageQueue.push({el,priority:/market-[0-9]/.test(path)?0:/feature-|radar-live/.test(path)?1:/products\//.test(path)?2:3})});
 imageQueue.sort((a,b)=>a.priority-b.priority);pumpImages();
}
function pumpImages(){while(activeImages<2&&imageQueue.length){const {el}=imageQueue.shift();if(!el.isConnected)continue;activeImages++;el.loading='eager';el.fetchPriority='low';el.src=el.dataset.src;
 imageReady(el).then(()=>{el.classList.add('image-ready');el.removeAttribute('data-src')}).catch(()=>{el.removeAttribute('src');el.classList.add('image-failed')}).finally(()=>{activeImages--;pumpImages()});
}}

const uiIcon=(name)=>`<svg viewBox="0 0 24 24" fill="none" aria-hidden="true" class="ui-icon">${name==='external'?'<path d="M7 17L17 7M7 7h10v10"/>':name==='bars'?'<path d="M5 19V14M12 19V9M19 19V4"/>':name==='arrow'?'<path d="M5 12h14m-6-6 6 6-6 6"/>':'<path d="M5 7h14M5 12h14M5 17h14"/>'}</svg>`;
const btn=(label,attr='',cls='btn')=>`<button class="${cls}" ${attr}>${label}${uiIcon('arrow')}</button>`;
const wave=()=>`<div class="wave"><svg viewBox="0 0 1672 200" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="wave-fill" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#a3d9ff"/><stop offset="1" stop-color="#dff3ff"/></linearGradient></defs><path d="M0 110Q130 10 270 65T510 112T770 68T1030 105T1250 50T1450 76T1672 10V200H0Z" fill="#71bfff" opacity=".65"/><path d="M0 55Q160 -10 315 57T605 60T883 101T1130 80T1380 100T1672 40V200H0Z" fill="url(#wave-fill)"/></svg></div>`;
const note='<p class="demo-note">Prévia visual · imagens do projeto e indicadores ilustrativos.</p>';
const heroCaptions=[['Várias plataformas, um só lugar.','Escolha onde vender e reúna sua operação.'],['Seu próximo produto começa aqui.','Pesquise tendências, analise oportunidades e transforme ideias em vendas.'],['Do produto ao anúncio, com clareza.','Organize seu catálogo e prepare a publicação.']];
const heroTitles=['Venda em várias<br> plataformas.','Encontre seu<br>próximo produto.','Transforme ideias<br> em novas vendas.'];
const heroBenefits=[['Várias plataformas','Uma operação no seu ritmo.'],['Mais oportunidades','Produtos com potencial para explorar.'],['Próximo passo organizado','Prepare, revise e escolha onde publicar.']];
const heroSlides=[['assets/reference/hero-cutout.png','Mercado Livre, Shopee e Amazon: um começo com mais possibilidades'],['assets/program/radar-trends.webp','Radar de tendências do Nixo'],['assets/program/product-category.png','Seleção de categoria no Nixo']];
let heroRequest=0,requestedSlide=slide;
function imageReady(image){return new Promise((resolve,reject)=>{if(image.complete){image.naturalWidth?resolve():reject(new Error('Image unavailable'));return}image.addEventListener('load',resolve,{once:true});image.addEventListener('error',reject,{once:true})}).then(()=>image.decode?image.decode():undefined)}
async function changeHeroSlide(next){
 const stage=$('.hero-stage');if(!stage)return;
 const request=++heroRequest;requestedSlide=(next+heroSlides.length)%heroSlides.length;
 const target=requestedSlide,panels=[...stage.querySelectorAll('[data-hero-panel]')],image=panels[target].querySelector('img');
 try{await imageReady(image)}catch(error){if(request===heroRequest&&stage.isConnected){requestedSlide=slide;toast('Não foi possível carregar este destaque. Tente novamente.')}return}
 if(request!==heroRequest||!stage.isConnected)return;
 panels.forEach((panel,i)=>{panel.classList.toggle('is-active',i===target);panel.setAttribute('aria-hidden',String(i!==target))});
 slide=target;$('.hero-title').innerHTML=heroTitles[slide];$('.hero-caption-title').textContent=heroCaptions[slide][0];$('.hero-caption-copy').textContent=heroCaptions[slide][1];$('.more-sales b').textContent=heroBenefits[slide][0];$('.more-sales small').textContent=heroBenefits[slide][1];if(window.gsap&&!reduced){const copy=[$('.hero-caption-title').parentElement,$('.more-sales b').parentElement];gsap.killTweensOf(copy);gsap.fromTo(copy,{opacity:0,y:5},{opacity:1,y:0,duration:.3,ease:'power2.out',clearProps:'transform,opacity'})}
 document.querySelectorAll('[data-slide-index]').forEach((dot,i)=>{dot.classList.toggle('active',i===slide);dot.setAttribute('aria-pressed',String(i===slide))});
}
function changeProductSlide(next){
 const grid=$('.product-grid');if(!grid)return;productSlide=(next+products.length)%products.length;
 const cards=[...grid.children];cards.sort((a,b)=>((Number(a.dataset.productIndex)-productSlide+products.length)%products.length)-((Number(b.dataset.productIndex)-productSlide+products.length)%products.length));cards.forEach(card=>grid.appendChild(card));
 document.querySelectorAll('[data-product-slide]').forEach((dot,i)=>{dot.classList.toggle('active',i===productSlide);dot.setAttribute('aria-pressed',String(i===productSlide))});
}
function referenceHeroWave(){return `<div class="wave reference-wave"><svg viewBox="0 0 1200 180" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="hero-wave-pale" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#eefaff"/><stop offset="1" stop-color="#d5efff"/></linearGradient></defs><path d="M0 55C155 115 205 -20 375 54S570 143 745 78S983 142 1200 8V180H0Z" fill="#74c5ff"/><path d="M0 118C160 160 183 -8 374 54S585 175 776 102S989 173 1200 55V180H0Z" fill="#b7e4ff"/><path d="M0 155C148 174 196 18 374 75S590 194 778 123S992 197 1200 80V180H0Z" fill="url(#hero-wave-pale)"/></svg></div>`}
function homeHero(){return `<section class="hero home-hero reference-hero"><div class="copy"><div class="eyebrow reveal">Sua operação, em um só lugar</div><h1 class="reveal hero-title">${heroTitles[slide]}</h1><p class="reveal">Do fornecedor ao anúncio: organize seus produtos e escolha onde vender.</p><div class="cta-row reveal">${btn('Testar por 3 dias','data-start="Teste de 3 dias"')}${btn('Ver plataforma','data-demo','btn outline')}</div></div><div class="hero-visual reveal-art"><div class="hero-stage">${heroSlides.map(([src,alt],i)=>`<div class="hero-slide ${slide===i?'is-active':''}" data-hero-panel="${i}" aria-hidden="${slide!==i}"><img src="${src}" alt="${alt}" class="hero-art ${i?'program-hero':'cutout-art float-art'}" width="${i?1536:1536}" height="1024" loading="eager" decoding="async" ${i===0?'fetchpriority="high"':''}>${i===0?'<span class="hero-clouds" aria-hidden="true"><i class="hero-cloud cloud-left"></i><i class="hero-cloud cloud-right"></i><i class="hero-cloud cloud-front"></i></span>':''}</div>`).join('')}</div></div></section><div class="hero-band reference-band reveal">${referenceHeroWave()}<section class="bottom-band"><div class="proof"><div><strong class="hero-caption-title">${heroCaptions[slide][0]}</strong><p class="hero-caption-copy">${heroCaptions[slide][1]}</p></div></div><div class="carousel-controls"><div class="arrows"><button class="round" data-slide="-1" aria-label="Destaque anterior">‹</button><button class="round" data-slide="1" aria-label="Próximo destaque">›</button></div><div class="dots">${[0,1,2].map(i=>`<button data-slide-index="${i}" class="${slide===i?'active':''}" aria-label="Destaque ${i+1}" aria-pressed="${slide===i}"></button>`).join('')}</div></div><button class="more-sales" data-page="recursos"><span class="native-chart" aria-hidden="true"><i></i><i></i><i></i></span><div><b>${heroBenefits[slide][0]}</b><small>${heroBenefits[slide][1]}</small></div><span>→</span></button></section></div>`}
const features=[['Oportunidades','Encontre produtos em alta com dados reais de mercado.','oportunidades'],['Fornecedores','Descubra e compare fornecedores confiáveis.','fornecedores'],['Agente de IA','Suporte para pesquisar, organizar e acompanhar suas atividades.','ia'],['Gestão','Organize seus produtos e acompanhe suas vendas.','gestao'],['Publicações','Publique no Mercado Livre e Shopee com mais agilidade.','publicacoes'],['Relatórios','Acompanhe seus resultados e tome melhores decisões.','relatorios']];
function resources(){return `<section class="features-layout"><div class="features-copy"><div class="eyebrow reveal">Tudo em um só lugar</div><h1 class="reveal">Tudo o que<br> você precisa<br> para vender mais</h1><p class="reveal">Pesquise oportunidades, encontre fornecedores e organize sua operação com um agente de IA ao seu lado.</p><div class="cta-row reveal">${btn('Testar por 3 dias','data-start="Teste de 3 dias"')}${btn('Ver demonstração','data-demo','btn outline')}</div></div><div class="feature-grid">${features.map(([t,d,k],i)=>`<button class="feature-card reveal" data-feature="${k}">${i===2?agentMark():img('feature-'+i,'Ilustração 3D: '+t,'','loading="eager" decoding="async" fetchpriority="low"')}<h3>${t}<span>›</span></h3><p>${d}</p></button>`).join('')}</div></section>`}
const markets=[['Mercado Livre','Publique e gerencie seus anúncios com mais alcance e visibilidade.','Mais alcance','Conecte-se a milhões de compradores.'],['Shopee','Simplifique a criação e gestão de seus produtos na Shopee.','Mais conversões','Aumente suas vendas com praticidade.'],['Amazon','Expanda suas vendas para o maior marketplace do mundo.','Mais oportunidades','Alcance clientes de todo o Brasil e no exterior.']];
function marketplaceCards(){return `<section class="platform-grid">${markets.map(([m,d,t,b],i)=>`<article class="market-card reveal" data-market-index="${i}"><div class="market-top">${img('market-'+i,m,'market-logo')}<div class="market-copy"><h3>${m}</h3><p>${d}</p></div><button class="market-action" data-market="${i}" aria-label="Conhecer ${m}">${uiIcon('external')}</button></div><div class="market-benefit"><span class="market-benefit-icon">${uiIcon('bars')}</span><div><b>${t}</b><small>${b}</small></div></div></article>`).join('')}</section>`}
function platforms(){return `<section class="hero platform-hero"><div class="copy"><div class="eyebrow reveal">Multi-plataforma</div><h1 class="reveal">Venda nas principais plataformas.</h1><p class="reveal">Escolha onde vender e organize sua operação em um só lugar. Novas plataformas fazem parte do futuro do Nixo.</p><div class="cta-row reveal">${btn('Testar por 3 dias','data-start="Teste de 3 dias"')}${btn('Ver demonstração','data-demo','btn outline')}</div></div><div class="hero-visual">${img('platform-hero','Mercado Livre, Shopee e Amazon','hero-art float-art reveal-art')}</div></section>${marketplaceCards()}`}
const products=[['Fone Bluetooth TWS','Eletrônicos','Alta tendência',92],['Luminária LED RGB','Casa e Decoração','Alta tendência',88],['Garrafa Térmica','Casa e Decoração','Média tendência',85],['Organizador de Maquiagem','Beleza','Alta tendência',80]];
function opportunities(){return `<section class="page-title"><h1 class="reveal">Oportunidades em destaque</h1><p class="reveal">Descubra produtos e nichos promissores com dados reais.</p></section><section class="opportunity-box reveal"><div class="product-grid">${products.map((_,j)=>{let i=(j+productSlide)%4;const [t,c,tr]=products[i];return `<article class="op-card reveal" data-product-index="${i}"><div class="op-card-photo">${img('product-'+i,t,'','loading="lazy"')}<div class="product-score"><span aria-hidden="true">▂▅▇</span><div><strong>${products[i][3]}</strong><small>Score</small></div></div></div><div class="op-info"><h3>${t}</h3><p>${c}</p><span class="trend ${i===2?'yellow':''}">↗ &nbsp; ${tr}</span><button data-product="${i}">Ver oportunidade <span>→</span></button></div></article>`}).join('')}</div><button class="round side-arrow" data-products="-1" aria-label="Produtos anteriores">‹</button><button class="round side-arrow right" data-products="1" aria-label="Próximos produtos">›</button><div class="dots">${[0,1,2,3].map(i=>`<button class="${productSlide===i?'active':''}" data-product-slide="${i}" aria-label="Grupo ${i+1}"></button>`).join('')}</div></section>${note}`}
const steps=[['Pesquise','Encontre produtos em alta com dados reais.'],['Analise','Veja concorrência, preço e fornecedores.'],['Prepare','Organize seu anúncio com o apoio do agente de IA.'],['Publique','Envie para Mercado Livre e Shopee e comece a vender.']];
function how(){return showcase(true)}
let billing='annual',selectedPlan=1;
const money=n=>n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const plans=[
 {name:'Essencial',monthly:129.90,annual:109.90,description:'Para organizar seus primeiros passos.',features:['Lista básica de fornecedores','Catálogo e rascunhos em um só lugar','Agente de IA para apoiar suas atividades','Preparação guiada de anúncios','Histórico das atividades','Central de ajuda para começar']},
 {name:'Profissional',monthly:199.90,annual:169.90,description:'Para dar ritmo à sua operação.',features:['Tudo do Essencial','Suporte especializado','Pesquisa e comparação de oportunidades','Preparação de anúncios em lote','Filas de publicação organizadas por prioridade','Acompanhamento de anúncios e atividades','Relatórios para orientar suas decisões']},
 {name:'Expansão',monthly:299.90,annual:249.90,description:'Para uma operação com mais possibilidades.',features:['Tudo do Profissional','Atendimento prioritário com suporte especializado','Apoio na configuração da operação','Visão consolidada das lojas e canais','Catálogos separados por loja e fornecedor','Relatórios por canal para comparar resultados','Acompanhamento para planejar a expansão']}
];
function planPrice(p){const value=p[billing],parts=money(value).split(',');return `<div class="price"><b>R$</b><strong>${parts[0]}<span class="cents">,${parts[1]}</span></strong><span>/ mês</span></div><p class="billing-detail">${billing==='annual'?`<span class="monthly-comparison">Mensal: R$ ${money(p.monthly)}/mês</span><b>Economize R$ ${money((p.monthly-value)*12)} por ano</b><span>Total anual: R$ ${money(value*12)}</span>`:'Cobrança mensal · sem compromisso anual'}</p>`}
function pricing(){return `<section class="page-title"><div class="eyebrow reveal">Escolha seu próximo passo</div><h1 class="reveal">Um plano para o seu momento.</h1><p class="reveal">Três opções para organizar sua operação. Teste por 3 dias ao escolher qualquer plano anual.</p></section><section class="plan-section"><div class="billing-toggle" role="group" aria-label="Período da assinatura"><button data-billing="monthly" aria-pressed="${billing==='monthly'}" class="${billing==='monthly'?'active':''}">Mensal</button><button data-billing="annual" aria-pressed="${billing==='annual'}" class="${billing==='annual'?'active':''}">Anual <span>Economize até 17%</span></button></div>${planNavigation()}<div class="plan-grid tier-plans">${plans.map((p,i)=>`<article data-plan-card="${i}" class="plan ${i===1?'pro':''} ${i===selectedPlan?'is-selected':''} reveal">${i===1?'<span class="popular">✦ Melhor opção</span>':''}<div class="plan-title"><span class="plan-symbol">${['◇','ϟ','↗'][i]}</span><div><h3>${p.name}</h3><p>${p.description}</p></div></div><div data-price-index="${i}">${planPrice(p)}</div><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><p class="plan-trial">${billing==='annual'?'3 dias de teste neste plano anual':'Prefere experimentar? Escolha o plano anual.'}</p>${btn('Escolher '+p.name,`data-plan="${i}"`,i===1?'btn blue':'btn plan-choice')}</article>`).join('')}</div><p class="plan-footnote">No anual, o valor por mês é equivalente ao total anual dividido por 12. O teste de 3 dias está disponível em qualquer plano anual.</p></section>`}
function planNavigation(){return `<div class="plan-navigation" role="group" aria-label="Comparar planos"><button type="button" class="plan-nav-arrow" data-plan-slide="-1" aria-label="Ver plano anterior" ${selectedPlan===0?'disabled':''}>‹</button><div class="plan-navigation-label" aria-live="polite" aria-atomic="true"><strong data-visible-plan>${plans[selectedPlan].name}</strong><span data-plan-position>Plano ${selectedPlan+1} de ${plans.length}</span></div><button type="button" class="plan-nav-arrow" data-plan-slide="1" aria-label="Ver próximo plano" ${selectedPlan===plans.length-1?'disabled':''}>›</button></div>`}
function syncPlanVisibility(){const mobile=window.innerWidth<=900;document.querySelectorAll('[data-plan-card]').forEach(el=>{const selected=Number(el.dataset.planCard)===selectedPlan;el.classList.toggle('is-selected',selected);el.setAttribute('aria-hidden',String(mobile&&!selected));el.inert=mobile&&!selected});document.querySelectorAll('[data-visible-plan]').forEach(el=>el.textContent=plans[selectedPlan].name);document.querySelectorAll('[data-plan-position]').forEach(el=>el.textContent=`Plano ${selectedPlan+1} de ${plans.length}`);document.querySelectorAll('[data-plan-slide]').forEach(el=>el.disabled=Number(el.dataset.planSlide)<0?selectedPlan===0:selectedPlan===plans.length-1)}
function changePlanSlide(delta){const next=Math.max(0,Math.min(plans.length-1,selectedPlan+delta));if(next===selectedPlan)return;selectedPlan=next;syncPlanVisibility();document.querySelectorAll(`[data-plan-card="${selectedPlan}"]`).forEach(el=>{if(observer)observer.unobserve(el);if(window.gsap&&!reduced){gsap.killTweensOf(el);gsap.fromTo(el,{opacity:0,x:delta>0?12:-12,y:0},{opacity:1,x:0,duration:.25,ease:'power2.out'})}else{el.style.opacity='1';el.style.transform='none'}})}
function changeBilling(value){if(!['annual','monthly'].includes(value))return;billing=value;document.querySelectorAll('[data-billing]').forEach(b=>{b.classList.toggle('active',b.dataset.billing===billing);b.setAttribute('aria-pressed',String(b.dataset.billing===billing))});document.querySelectorAll('[data-price-index]').forEach(el=>{el.innerHTML=planPrice(plans[Number(el.dataset.priceIndex)])});document.querySelectorAll('.plan-trial').forEach(el=>el.textContent=billing==='annual'?'3 dias de teste neste plano anual':'Prefere experimentar? Escolha o plano anual.')}
function choosePlan(index){const p=plans[index];if(!p)return;modal(`<h2>${p.name} · ${billing==='annual'?'Anual':'Mensal'}</h2><p>R$ ${money(p[billing])} por mês${billing==='annual'?`, equivalente a R$ ${money(p.annual*12)} por ano. Inclui 3 dias de teste.`:'. Cobrança mensal.'}</p><p>Explore o Nixo na demonstração. A contratação e o pagamento ainda não estão conectados.</p><a class="btn blue" href="demo/">Explorar demonstração →</a>`)}

const faqs=[['O Nixo funciona no Mercado Livre e na Shopee?','A proposta do Nixo é reunir a preparação e a gestão de produtos para Mercado Livre, Shopee e Amazon. Este site é uma demonstração visual; não está conectado às contas dos marketplaces.'],['Preciso ter CNPJ para usar o Nixo?','Os requisitos dependem da plataforma, do tipo de conta e da sua atividade comercial. Confira as regras oficiais antes de operar.'],['Os fornecedores são confiáveis?','O Nixo deve ajudar a pesquisar e organizar fornecedores. Antes de vender, valide documentação, disponibilidade, qualidade dos produtos e condições comerciais.'],['Como o agente de IA me ajuda?','O agente apoia a pesquisa de oportunidades, a organização das informações e o acompanhamento das atividades. Você mantém o controle das decisões e revisa as sugestões antes de usá-las.'],['Quanto custa para usar o Nixo?','Os planos mensais custam R$129,90, R$199,90 e R$299,90. No anual, os valores equivalentes são R$109,90, R$169,90 e R$249,90 por mês, com cobrança anual. Qualquer plano anual inclui 3 dias de teste. O Essencial inclui lista básica de fornecedores.']];
function faq(){return `<section class="faq-panel reveal"><div class="faq-copy"><div class="eyebrow">Suporte</div><h1>Perguntas<br> frequentes</h1><p class="subtitle">Tire suas dúvidas sobre o Nixo.</p><p>Reunimos as principais perguntas para te ajudar a entender como o Nixo funciona e como ele pode simplificar suas vendas no Mercado Livre, Shopee e Amazon.</p><div class="support-tile"><div><h3>Ainda tem dúvidas?</h3><p>Encontre apoio para o próximo passo.</p>${btn('Falar com suporte','data-support','btn blue')}</div>${img('support-headset','Headset de suporte Nixo','headset-art')}</div></div><div class="faq-list">${faqs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary><span class="faq-icon">${i===0?img('market-0','Mercado Livre'):['','▤','◆','✦','▥'][i]}</span>${q}<span class="chevron">⌄</span></summary><p>${a}</p></details>`).join('')}</div></section>`}
function agentMark(){return `<div class="agent-emblem" aria-hidden="true"><svg viewBox="0 0 120 120" fill="none"><defs><linearGradient id="agent-gradient" x1="20" y1="15" x2="100" y2="100" gradientUnits="userSpaceOnUse"><stop stop-color="#827bff"/><stop offset="1" stop-color="#3f2dde"/></linearGradient></defs><rect x="14" y="14" width="92" height="92" rx="27" fill="url(#agent-gradient)"/><rect x="35" y="33" width="50" height="42" rx="13" fill="#fff"/><path d="M45 73l-3 12 17-11" fill="#fff"/><circle cx="48" cy="54" r="4" fill="#5350db"/><circle cx="60" cy="54" r="4" fill="#5350db"/><circle cx="72" cy="54" r="4" fill="#5350db"/><path d="M93 12l3 9 9 3-9 3-3 9-3-9-9-3 9-3z" fill="#c8b5ff"/></svg></div>`}
const tutorialSteps=[['Escolha o produto','Encontre a categoria ideal e selecione o tipo de produto que você quer vender.','product-start','Escolha de produtos: camiseta, moletom e tênis'],['Organize as fotos','Faça o upload das imagens, escolha a foto principal e organize a ordem como preferir.','product-images','Organização das fotos de uma camiseta, com foto principal em destaque'],['Defina preço e publique','Informe o preço, ajuste os detalhes e publique seu produto em poucos cliques.','product-price','Preço, estoque, resumo e botão de publicar o produto']];
function categoryTiles(){const icons=[['Roupas','<path d="m8 4-5 4 3 5 3-2v10h10V11l3 2 3-5-5-4-3 2h-5z"/>'],['Calçados','<path d="m6 9 5 5c2 2 6 1 9 3l3 2v3H3v-6l3-7z"/><path d="M3 18h20M11 13l3-2m0 5 3-2"/>'],['Bolsas','<path d="M5 9h18l-2 14H7L5 9z"/><path d="M10 10V6a4 4 0 0 1 8 0v4"/>'],['Casa','<rect x="6" y="4" width="16" height="14" rx="4"/><path d="M6 13H3v9h22v-9h-3M7 22v3m14-3v3"/>'],['Eletrônicos','<rect x="8" y="2" width="12" height="24" rx="3"/><path d="M12 22h4"/>'],['Outros','<circle cx="6" cy="14" r="1"/><circle cx="14" cy="14" r="1"/><circle cx="22" cy="14" r="1"/>']];return `<div class="how-categories" aria-label="Exemplos de categorias">${icons.map(([label,path],i)=>`<span class="how-category ${i===0?'selected':''}"><svg viewBox="0 0 28 28" fill="none" aria-hidden="true">${path}</svg><span>${label}</span></span>`).join('')}</div>`}
function showcase(standalone=false){const heading=standalone?'h1':'h2';return `<section class="reference-how"><div class="reference-how-inner"><div class="reference-how-heading reveal"><span class="how-brand-pill">Nixo</span><${heading}>Como funciona</${heading}><p>Em poucos passos, seu produto fica pronto para vender.<br>Simples, rápido e sem complicação.</p></div><div class="reference-how-steps">${tutorialSteps.map(([title,description,screenId,alt],i)=>`<article class="reference-how-card how-card-${i+1} reveal"><div class="reference-how-copy"><span class="how-step-number" aria-label="Etapa ${i+1}">${i+1}</span><h3>${title}</h3><p>${description}</p>${i===0?categoryTiles():''}</div><button type="button" class="how-art" data-screen="${screenId}" aria-label="Ver a tela do programa: ${title}"><img data-src="assets/tutorial/step-${i+1}.webp" class="queued-image" alt="${alt}" width="1200" height="900" decoding="async"></button></article>`).join('')}</div></div></section>`}

function agentSection(){return `<section class="agent-section"><div class="agent-copy"><div class="eyebrow reveal">Inteligência que acompanha você</div><h2 class="reveal">Um agente de IA<br> ao seu lado.</h2><p class="reveal">Apoio para pesquisar, organizar e acompanhar as atividades da sua operação, um passo de cada vez.</p><ul class="agent-benefits"><li class="reveal"><b>Encontre possibilidades.</b><span>Apoio na pesquisa de oportunidades e fornecedores.</span></li><li class="reveal"><b>Organize o próximo passo.</b><span>Informações reunidas para facilitar suas decisões.</span></li><li class="reveal"><b>Acompanhe suas atividades.</b><span>Mais clareza sobre o que está em andamento.</span></li></ul>${btn('Conhecer o fluxo','data-demo','btn blue reveal')}</div><div class="agent-screen reveal"><button data-screen="radar-live" aria-label="Ampliar tela de atividades do Nixo">${screen('radar-live','Radar do Nixo: andamento das atividades')}</button><div class="agent-caption"><span class="agent-presence"></span><b>Você decide. O agente dá suporte.</b></div></div></section>`}
function homePlatforms(){return `<section class="home-market-section"><div class="page-title"><div class="eyebrow reveal">Escolha seu destino</div><h2 class="reveal">Mais plataformas.<br class="mobile-break"> Mais possibilidades.</h2><p class="reveal">Mercado Livre, Shopee e Amazon são o começo. O futuro do Nixo inclui novas plataformas para você ir além.</p></div>${marketplaceCards()}</section>`}
function home(){return `<div class="full-home">${homeHero()}<div class="long-section">${homePlatforms()}</div><div class="long-section">${resources()}</div><div class="long-section">${agentSection()}</div><div class="long-section">${opportunities()}</div><div class="long-section">${showcase()}</div><div class="long-section">${pricing()}</div><div class="long-section">${faq()}</div></div>`}
function animate(){if(observer){observer.disconnect();observer=null}if(!window.gsap||reduced)return;const targets=[...document.querySelectorAll('.reveal,.reveal-art')];if('IntersectionObserver' in window){gsap.set(targets,{opacity:0,y:24});observer=new IntersectionObserver(items=>{items.forEach(item=>{if(!item.isIntersecting)return;const art=item.target.classList.contains('reveal-art');gsap.to(item.target,{opacity:1,y:0,duration:art?1:.7,ease:'power3.out'});observer.unobserve(item.target)})},{threshold:.08});targets.forEach(el=>observer.observe(el))}else{entry=gsap.fromTo('.reveal,.reveal-art',{opacity:0,y:24},{opacity:1,y:0,duration:.8,stagger:.045,ease:'power3.out'})}gsap.to('.float-art',{y:7,duration:3.2,repeat:-1,yoyo:true,stagger:.25,ease:'sine.inOut'});gsap.to('.hero-cloud',{xPercent:5,duration:7,repeat:-1,yoyo:true,stagger:1.2,ease:'sine.inOut'})}
function render(keep=false){heroRequest++;requestedSlide=slide;if(window.gsap)gsap.killTweensOf('*');main.innerHTML=({inicio:home,recursos:resources,plataformas:platforms,oportunidades:opportunities,funcionamento:how,planos:pricing,perguntas:faq})[page]();$('#nav').innerHTML=Object.entries(tabs).map(([k,l])=>`<button data-page="${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}>${l}</button>`).join('')+'<button type="button" data-open-demo>Demonstração</button>';$('#motion').textContent=reduced?'Ativar movimento':'Pausar movimento';enqueueImages(main);syncPlanVisibility();animate();if(!keep)scrollTo({top:0,behavior:'instant'})}
function navigate(){closeMenu();const target=location.hash.slice(1);page=tabs[target]?target:'inicio';render()}
function modal(html,wide=false){$('#dialog').classList.toggle('wide',wide);$('#modal-content').innerHTML=html;enqueueImages($('#modal-content'));$('#dialog').showModal()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function closeMenu(){$('header').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Abrir navegação');$('#nav').inert=window.innerWidth<=1150}
function go(k){closeMenu();$('#dialog').close();if(page===k){scrollTo({top:0,behavior:reduced?'instant':'smooth'});return}location.hash=k}
function searchResults(q=''){const results=Object.entries(tabs).filter(([k,v])=>v.toLowerCase().includes(q.toLowerCase()));$('#search-results').innerHTML=results.map(([k,v])=>`<button data-page="${k}">${v} →</button>`).join('')||'<p>Nenhuma página encontrada.</p>'}
$('#menu-toggle').addEventListener('click',()=>{const open=$('#menu-toggle').getAttribute('aria-expanded')!=='true';$('header').classList.toggle('menu-open',open);$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Fechar navegação':'Abrir navegação');$('#nav').inert=!open});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
$('#search-button').addEventListener('click',()=>{modal('<h2>O que você procura?</h2><input id="site-search" type="search" placeholder="Recursos, plataformas, planos…" aria-label="Buscar página"><div class="search-results" id="search-results"></div>');searchResults();$('#site-search').focus()});
$('#motion').addEventListener('click',()=>{reduced=!reduced;render(true)});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
const featureInfo={fornecedores:['Fornecedores','Pesquise parceiros e valide as condições comerciais. A operação segue a regra de um fornecedor ativo por loja.'],ia:['Agente de IA','Um agente ao seu lado para pesquisar oportunidades, organizar informações e acompanhar suas atividades. Você revisa as sugestões e mantém o controle das decisões.'],gestao:['Gestão','Organize catálogo, rascunhos e operações. Explore a demonstração para conhecer o fluxo visual.'],publicacoes:['Publicações','Revise seu produto e escolha o destino. A publicação real depende da integração oficial e de sua confirmação.'],relatorios:['Relatórios','Acompanhe dados confirmados das suas operações. Nesta prévia, todos os indicadores são exemplos visuais.']};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-open-demo')){closeMenu();location.assign('demo/');return;}if(b.dataset.planSlide!==undefined)changePlanSlide(Number(b.dataset.planSlide));if(b.dataset.billing)changeBilling(b.dataset.billing);if(b.dataset.plan!==undefined)choosePlan(Number(b.dataset.plan));if(b.classList.contains('close'))$('#dialog').close();if(b.dataset.page)go(b.dataset.page);if(b.hasAttribute('data-demo'))modal(`<h2>Explore o Nixo.</h2><p>Conheça o fluxo de descoberta de produtos, edição de anúncios e escolha da plataforma na demonstração interativa.</p><a class="btn blue" href="demo/">Abrir demonstração <span>→</span></a><p>Dados de exemplo. Nenhuma publicação real.</p>`);if(b.dataset.start)modal(`<h2>Experimente o Nixo por 3 dias.</h2><p>O teste está disponível em qualquer plano anual. Escolha entre Essencial, Profissional e Expansão, a partir do equivalente a R$109,90/mês no anual.</p>${btn('Conhecer os planos','data-page="planos"','btn blue')}`);if(b.dataset.market){const i=Number(b.dataset.market);modal(`${img('market-'+i,markets[i][0],'mini-art')}<h2>${markets[i][0]}</h2><p>${markets[i][1]}</p><p>Para operar de verdade, o Nixo precisa da integração oficial e da autorização da sua conta.</p><a class="btn blue" href="demo/#contas">Ver conexão na demonstração <span>→</span></a>`)}if(b.dataset.product){const i=Number(b.dataset.product),p=products[i];modal(`${img('product-'+i,p[0],'reference')}<h2>${p[0]}</h2><p>${p[1]} · Score ilustrativo ${p[3]} · ${p[2]}</p><p>Produto e indicadores da referência visual. Disponibilidade, preço e fornecedor precisam ser validados com dados reais.</p>${btn('Explorar o fluxo','data-demo','btn blue')}`)}if(b.dataset.screen){const name=b.dataset.screen;if(['radar-trends','radar-live','product-start','product-details','product-images','product-price','product-review','product-category'].includes(name))modal(`${screen(name,'Tela do Nixo em tamanho original','program-original')}<p>Imagem do projeto Nixo.</p>`,true)}if(b.dataset.feature){const k=b.dataset.feature;if(k==='oportunidades')go(k);else{const [t,d]=featureInfo[k];modal(`<h2>${t}</h2><p>${d}</p><a class="btn blue" href="demo/">Explorar demonstração <span>→</span></a>`)}}if(b.hasAttribute('data-support'))modal('<h2>Como podemos ajudar?</h2><p>Veja as perguntas frequentes ou explore o fluxo de demonstração. O canal de atendimento ainda não foi conectado nesta prévia.</p><a class="btn blue" href="demo/">Explorar demonstração <span>→</span></a>');if(b.dataset.step){const i=Number(b.dataset.step);modal(`${img('how-'+i,steps[i][0],'mini-art')}<h2>${steps[i][0]}</h2><p>${steps[i][1]}</p><a class="btn blue" href="demo/#vender">Experimentar o fluxo <span>→</span></a>`)}if(b.dataset.slide)changeHeroSlide(requestedSlide+Number(b.dataset.slide));if(b.dataset.slideIndex!==undefined)changeHeroSlide(Number(b.dataset.slideIndex));if(b.dataset.products)changeProductSlide(productSlide+Number(b.dataset.products));if(b.dataset.productSlide!==undefined)changeProductSlide(Number(b.dataset.productSlide));});
document.addEventListener('input',e=>{if(e.target.id==='site-search')searchResults(e.target.value)});
window.addEventListener('hashchange',navigate);window.addEventListener('resize',()=>{if(window.innerWidth>1150)closeMenu();syncPlanVisibility()});navigate();

document.getElementById('footer-year').textContent=String(new Date().getFullYear());
